// hackGrow.js
/**
 * Minimal Bitburner hack/grow script to start increasing money.
 *
 * @param {NS} ns - The Bitburner namespace.
 */
export async function main(ns) {
    const servers = Object.keys(ns.getHackingTargets()).filter(s => ns.getServerMaxMoney(s) > 0);

    if (servers.length === 0) {
        ns.tprint('No target servers found with money.');
        return;
    }

    const targetServer = servers.reduce((a, b) => ns.getServerMaxMoney(a) > ns.getServerMaxMoney(b) ? a : b);

    while (true) {
        if (ns.hack(targetServer)) {
            await ns.sleep(100);
            ns.grow(targetServer);
        } else {
            await ns.sleep(1000);
        }
    }
}
